const fs=require('fs');const path=require('path');const {spawnSync}=require('child_process');const root=process.cwd();const html=fs.readFileSync(path.join(root,'index.html'),'utf8');const match=html.match(/<body[^>]*>([\s\S]*?)</body>/i);if(!match)throw new Error('Could not find portfolio body in index.html');const markup=match[1].replace(/ class=/g,'className=').replace(/<span id="year"></span>/,'{new Date().getFullYear()}');fs.mkdirSync(path.join(root,'app'),{recursive:true});fs.writeFileSync(path.join(root,'app','page.tsx'),`"use client";

import { useEffect } from "react";

export default function Home() {
  useEffect(() => {
    const menuButton = document.querySelector<HTMLButtonElement>(".menu-toggle");
    const navLinks = document.querySelector<HTMLElement>(".nav-links");
    if (menuButton && navLinks) {
      const setMenuOpen = (isOpen: boolean) => {
        navLinks.classList.toggle("open", isOpen);
        menuButton.setAttribute("aria-expanded", String(isOpen));
        menuButton.setAttribute("aria-label", isOpen ? "Close navigation" : "Open navigation");
      };
      menuButton.addEventListener("click", () => setMenuOpen(menuButton.getAttribute("aria-expanded") !== "true"));
      navLinks.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => setMenuOpen(false)));
      document.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && menuButton.getAttribute("aria-expanded") === "true") { setMenuOpen(false); menuButton.focus(); }
      });
    }
    const items = document.querySelectorAll(".reveal");
    if ("IntersectionObserver" in window && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      const observer = new IntersectionObserver((entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) { entry.target.classList.add("visible"); observer.unobserve(entry.target); }
      }), { threshold: 0.12 });
      items.forEach((item) => observer.observe(item));
      return () => observer.disconnect();
    }
    items.forEach((item) => item.classList.add("visible"));
  }, []);

  return (
    <>
${markup}
    </>
  );
}
`);fs.writeFileSync(path.join(root,'app','layout.tsx'),`import type { Metadata } from "next";
